 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(x for row in grid for x in row)
    bg = counts.most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    if not points:
        return [row[:] for row in grid]
    rmin = min(r for r, c in points)
    rmax = max(r for r, c in points)
    cmin = min(c for r, c in points)
    cmax = max(c for r, c in points)
    row_counts = Counter(r for r, c in points)
    col_counts = Counter(c for r, c in points)
    # Strongly represented rows/columns and the outermost bounds define the
    # interrupted grid lines; fill their gaps with the completing color.
    line_rows = {rmin, rmax} | {r for r, n in row_counts.items() if n >= 3}
    line_cols = {cmin, cmax} | {c for c, n in col_counts.items() if n >= 3}
    out = [row[:] for row in grid]
    for r in range(rmin, rmax + 1):
        for c in range(cmin, cmax + 1):
            if (r in line_rows or c in line_cols) and grid[r][c] == bg:
                out[r][c] = 2
    return out
