 "content": "from collections import Counter

def _has_pair(indices):
    values = sorted(indices)
    return any(b == a + 1 for a, b in zip(values, values[1:]))

def transform(grid):
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    points = [(r, c) for r in range(h) for c in range(w) if grid[r][c] != bg]
    out = [row[:] for row in grid]
    if not points:
        return out
    r0 = min(r for r, c in points)
    r1 = max(r for r, c in points)
    c0 = min(c for r, c in points)
    c1 = max(c for r, c in points)
    # Extend only lines that already contain a contiguous fragment of at
    # least two marks; isolated aligned endpoints are not intended lines.
    for r in range(r0, r1 + 1):
        cols = [c for rr, c in points if rr == r]
        if _has_pair(cols):
            for c in range(c0, c1 + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    for c in range(c0, c1 + 1):
        rows = [r for r, cc in points if cc == c]
        if _has_pair(rows):
            for r in range(r0, r1 + 1):
                if grid[r][c] == bg:
                    out[r][c] = 2
    return out
